func (this *Paradex) ParseMarket(market any) any {
	//
	//     {
	//         "symbol": "BODEN-USD-PERP",
	//         "base_currency": "BODEN",
	//         "quote_currency": "USD",
	//         "settlement_currency": "USDC",
	//         "order_size_increment": "1",
	//         "price_tick_size": "0.00001",
	//         "min_notional": "200",
	//         "open_at": 1717065600000,
	//         "expiry_at": 0,
	//         "asset_kind": "PERP",
	//         "position_limit": "2000000",
	//         "price_bands_width": "0.2",
	//         "max_open_orders": 50,
	//         "max_funding_rate": "0.05",
	//         "delta1_cross_margin_params": {
	//             "imf_base": "0.2",
	//             "imf_shift": "180000",
	//             "imf_factor": "0.00071",
	//             "mmf_factor": "0.5"
	//         },
	//         "price_feed_id": "9LScEHse1ioZt2rUuhwiN6bmYnqpMqvZkQJDNUpxVHN5",
	//         "oracle_ewma_factor": "0.14999987905913592",
	//         "max_order_size": "520000",
	//         "max_funding_rate_change": "0.0005",
	//         "max_tob_spread": "0.2"
	//     }
	//
	// {
	//     "symbol":"BTC-USD-96000-C",
	//     "base_currency":"BTC",
	//     "quote_currency":"USD",
	//     "settlement_currency":"USDC",
	//     "order_size_increment":"0.001",
	//     "price_tick_size":"0.01",
	//     "min_notional":"100",
	//     "open_at":"1736764200000",
	//     "expiry_at":"0",
	//     "asset_kind":"PERP_OPTION",
	//     "market_kind":"cross",
	//     "position_limit":"10",
	//     "price_bands_width":"0.05",
	//     "iv_bands_width":"0.05",
	//     "max_open_orders":"100",
	//     "max_funding_rate":"0.02",
	//     "option_cross_margin_params":{
	//        "imf":{
	//           "long_itm":"0.2",
	//           "short_itm":"0.15",
	//           "short_otm":"0.1",
	//           "short_put_cap":"0.5",
	//           "premium_multiplier":"1"
	//        },
	//        "mmf":{
	//           "long_itm":"0.1",
	//           "short_itm":"0.075",
	//           "short_otm":"0.05",
	//           "short_put_cap":"0.5",
	//           "premium_multiplier":"0.5"
	//        }
	//     },
	//     "price_feed_id":"GVXRSBjFk6e6J3NbVPXohDJetcTjaeeuykUpbQF8UoMU",
	//     "oracle_ewma_factor":"0.20000046249626113",
	//     "max_order_size":"2",
	//     "max_funding_rate_change":"0.02",
	//     "max_tob_spread":"0.2",
	//     "interest_rate":"0.0001",
	//     "clamp_rate":"0.02",
	//     "option_type":"CALL",
	//     "strike_price":"96000",
	//     "funding_period_hours":"24",
	//     "tags":[
	//     ]
	//  }
	//
	var assetKind any = this.SafeString(market, "asset_kind")
	var isOptionPerpetual bool = (IsEqual(assetKind, "PERP_OPTION"))
	var isOptionDelivery bool = (IsEqual(assetKind, "OPTION"))
	var isOption bool = IsTrue(isOptionPerpetual) || IsTrue(isOptionDelivery)
	var typeVar any = Ternary(IsTrue((isOption)), "option", "swap")
	var isSwap bool = (IsEqual(typeVar, "swap"))
	var marketId any = this.SafeString(market, "symbol")
	var quoteId any = this.SafeString(market, "quote_currency")
	var baseId any = this.SafeString(market, "base_currency")
	var quote any = this.SafeCurrencyCode(quoteId)
	var base any = this.SafeCurrencyCode(baseId)
	var settleId any = this.SafeString(market, "settlement_currency")
	var settle any = this.SafeCurrencyCode(settleId)
	var symbol any = Add(Add(Add(Add(base, "/"), quote), ":"), settle)
	var expiry any = this.SafeInteger(market, "expiry_at")
	var optionType any = this.SafeString(market, "option_type")
	var strikePrice any = this.SafeString(market, "strike_price")
	var takerFee any = this.ParseNumber("0.0003")
	var makerFee any = this.ParseNumber("-0.00005")
	if IsTrue(isOption) {
		var optionTypeSuffix any = Ternary(IsTrue((IsEqual(optionType, "CALL"))), "C", "P")
		var deliveryValue any = Ternary(IsTrue((IsEqual(expiry, 0))), "", Add(this.Yymmdd(expiry), "-"))
		symbol = Add(Add(Add(Add(Add(symbol, "-"), deliveryValue), strikePrice), "-"), optionTypeSuffix)
		makerFee = this.ParseNumber("0.0003")
	} else {
		expiry = nil
	}
	var expireDatetime any = Ternary(IsTrue((IsEqual(expiry, 0))), nil, this.Iso8601(expiry))
	return this.SafeMarketStructure(map[string]any{
		"id":             marketId,
		"symbol":         symbol,
		"base":           base,
		"quote":          quote,
		"settle":         settle,
		"baseId":         baseId,
		"quoteId":        quoteId,
		"settleId":       settleId,
		"type":           typeVar,
		"spot":           false,
		"margin":         nil,
		"swap":           isSwap,
		"future":         false,
		"option":         isOption,
		"active":         this.SafeBool(market, "enableTrading"),
		"contract":       true,
		"linear":         true,
		"inverse":        false,
		"taker":          takerFee,
		"maker":          makerFee,
		"contractSize":   this.ParseNumber("1"),
		"expiry":         expiry,
		"expiryDatetime": expireDatetime,
		"strike":         this.ParseNumber(strikePrice),
		"optionType":     this.SafeStringLower(market, "option_type"),
		"precision": map[string]any{
			"amount": this.SafeNumber(market, "order_size_increment"),
			"price":  this.SafeNumber(market, "price_tick_size"),
		},
		"limits": map[string]any{
			"leverage": map[string]any{
				"min": nil,
				"max": nil,
			},
			"amount": map[string]any{
				"min": nil,
				"max": this.SafeNumber(market, "max_order_size"),
			},
			"price": map[string]any{
				"min": nil,
				"max": nil,
			},
			"cost": map[string]any{
				"min": this.SafeNumber(market, "min_notional"),
				"max": nil,
			},
		},
		"created": nil,
		"info":    market,
	})
}
func (this *Paradex) ParseTradingFee(fee any, optionalArgs ...any) any {
	//
	//     {
	//         "symbol": "BTC-USD-PERP",
	//         "fee_config": {
	//             "api_fee": {
	//                 "maker_fee": {
	//                     "fee": "0.000075",
	//                     "fee_cap": "0.125",
	//                     "fee_floor": "-0.125"
	//                 },
	//                 "taker_fee": {
	//                     "fee": "0.000125",
	//                     "fee_cap": "0.125",
	//                     "fee_floor": "-0.125"
	//                 }
	//             }
	//         }
	//     }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var marketId any = this.SafeString(fee, "symbol")
	market = this.SafeMarket(marketId, market)
	var feeConfig any = this.SafeDict(fee, "fee_config", map[string]any{})
	var apiFee any = this.SafeDict(feeConfig, "api_fee", map[string]any{})
	var makerFee any = this.SafeDict(apiFee, "maker_fee", map[string]any{})
	var takerFee any = this.SafeDict(apiFee, "taker_fee", map[string]any{})
	return map[string]any{
		"info":       fee,
		"symbol":     GetValue(market, "symbol"),
		"maker":      this.SafeNumber(makerFee, "fee", this.SafeNumber(market, "maker")),
		"taker":      this.SafeNumber(takerFee, "fee", this.SafeNumber(market, "taker")),
		"percentage": true,
		"tierBased":  false,
	}
}

