	_ = params
	if IsTrue(IsEqual(this.Markets, nil)) {

		retRes79512 := (<-this.LoadMarketsAsync())
		PanicOnError(retRes79512)
	}

	response := (<-this.PublicGetMarkets(params))
	PanicOnError(response)
	//
	//     {
	//         "results": [
	//             {
	//                 "symbol": "BTC-USD-PERP",
	//                 "fee_config": {
	//                     "api_fee": {
	//                         "maker_fee": {
