func (this *Paradex) ParseTrade(trade any, optionalArgs ...any) any {
	//
	// fetchTrades (public)
	//
	//     {
	//         "id": "1718154353750201703989430001",
	//         "market": "BTC-USD-PERP",
	//         "side": "BUY",
	//         "size": "0.026",
	//         "price": "69578.2",
	//         "created_at": 1718154353750,
	//         "trade_type": "FILL"
	//     }
	//
	// fetchMyTrades (private)
	//
	//     {
	//         "id": "1718947571560201703986670001",
	//         "side": "BUY",
	//         "liquidity": "TAKER",
	//         "market": "BTC-USD-PERP",
	//         "order_id": "1718947571540201703992340000",
	//         "price": "64852.9",
	//         "size": "0.01",
	//         "fee": "0.1945587",
	//         "fee_currency": "USDC",
	//         "created_at": 1718947571569,
	//         "remaining_size": "0",
	//         "client_id": "",
	//         "fill_type": "FILL"
	//     }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var marketId any = this.SafeString(trade, "market")
	market = this.SafeMarket(marketId, market)
	var id any = this.SafeString(trade, "id")
	var timestamp any = this.SafeInteger(trade, "created_at")
	var priceString any = this.SafeString(trade, "price")
	var amountString any = this.SafeString(trade, "size")
	var side any = this.SafeStringLower(trade, "side")
	var liability any = this.SafeStringLower(trade, "liquidity", "taker")
	var isTaker bool = IsEqual(liability, "taker")
	var takerOrMaker any = Ternary(IsTrue((isTaker)), "taker", "maker")
	var currencyId any = this.SafeString(trade, "fee_currency")
	var code any = this.SafeCurrencyCode(currencyId)
	return this.SafeTrade(map[string]any{
		"info":         trade,
		"id":           id,
		"order":        this.SafeString(trade, "order_id"),
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"symbol":       GetValue(market, "symbol"),
		"type":         nil,
		"takerOrMaker": takerOrMaker,
		"side":         side,
		"price":        priceString,
		"amount":       amountString,
		"cost":         nil,
		"fee": map[string]any{
			"cost":     this.SafeString(trade, "fee"),
			"currency": code,
			"rate":     nil,
		},
	}, market)
}

